            public ErrorMask Combine(ErrorMask? rhs)
            {
                if (rhs == null) return this;
                var ret = new ErrorMask();
                ret.EDID = this.EDID.Combine(rhs.EDID);
                ret.FormTags = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.FormTags?.Overall, rhs.FormTags?.Overall), Noggog.ExceptionExt.Combine(this.FormTags?.Specific, rhs.FormTags?.Specific));
                ret.IDLF = this.IDLF.Combine(rhs.IDLF);
                ret.IsFO3 = this.IsFO3.Combine(rhs.IsFO3);
                ret.IDLC = this.IDLC.Combine(rhs.IDLC);
                ret.IDLT = this.IDLT.Combine(rhs.IDLT);
                ret.IDLA = this.IDLA.Combine(rhs.IDLA);
                ret.IsSF1 = this.IsSF1.Combine(rhs.IsSF1);
                ret.CNAM = this.CNAM.Combine(rhs.CNAM);
                ret.Quest = this.Quest.Combine(rhs.Quest);
                ret.XNAM = this.XNAM.Combine(rhs.XNAM);
                ret.POBA = this.POBA.Combine(rhs.POBA);
                ret.IdleAnimation = this.IdleAnimation.Combine(rhs.IdleAnimation);
                ret.POEA = this.POEA.Combine(rhs.POEA);
                ret.IdleAnimation2 = this.IdleAnimation2.Combine(rhs.IdleAnimation2);
                ret.POCA = this.POCA.Combine(rhs.POCA);
                ret.IdleAnimation3 = this.IdleAnimation3.Combine(rhs.IdleAnimation3);
                ret.ANAM = this.ANAM.Combine(rhs.ANAM);
                ret.BNAM = this.BNAM.Combine(rhs.BNAM);
                ret.Conditions = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, Condition.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.Conditions?.Overall, rhs.Conditions?.Overall), Noggog.ExceptionExt.Combine(this.Conditions?.Specific, rhs.Conditions?.Specific));
                ret.FNAM = this.FNAM.Combine(rhs.FNAM);
                ret.PFO2 = this.PFO2.Combine(rhs.PFO2);
                ret.PFOR = this.PFOR.Combine(rhs.PFOR);
                ret.PKC2 = this.PKC2.Combine(rhs.PKC2);
                ret.PKCU = this.PKCU.Combine(rhs.PKCU, (l, r) => l.Combine(r));
                ret.PKDT = this.PKDT.Combine(rhs.PKDT, (l, r) => l.Combine(r));
                ret.PNAM = this.PNAM.Combine(rhs.PNAM);
                ret.Root = this.Root.Combine(rhs.Root, (l, r) => l.Combine(r));
                ret.PSDT = this.PSDT.Combine(rhs.PSDT, (l, r) => l.Combine(r));
                ret.PTDA = this.PTDA.Combine(rhs.PTDA, (l, r) => l.Combine(r));
                ret.TPIC = this.TPIC.Combine(rhs.TPIC);
                ret.VMAD = this.VMAD.Combine(rhs.VMAD);
                ret.CIS1 = this.CIS1.Combine(rhs.CIS1);
                ret.CIS2 = this.CIS2.Combine(rhs.CIS2);
                ret.PDTO = this.PDTO.Combine(rhs.PDTO);
                ret.PLDT = this.PLDT.Combine(rhs.PLDT);
                ret.UNAM = this.UNAM.Combine(rhs.UNAM);
                return ret;
            }
            public static ErrorMask? Combine(ErrorMask? lhs, ErrorMask? rhs)
            {
                if (lhs != null && rhs != null) return lhs.Combine(rhs);
                return lhs ?? rhs;
