        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IPackageGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.IDLA, out var IDLAInfo))
            {
                yield return IDLAInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Quest, out var QuestInfo))
            {
                yield return QuestInfo;
            }
            if (FormLinkInformation.TryFactory(obj.IdleAnimation, out var IdleAnimationInfo))
            {
                yield return IdleAnimationInfo;
            }
            if (FormLinkInformation.TryFactory(obj.IdleAnimation2, out var IdleAnimation2Info))
            {
                yield return IdleAnimation2Info;
            }
            if (FormLinkInformation.TryFactory(obj.IdleAnimation3, out var IdleAnimation3Info))
            {
                yield return IdleAnimation3Info;
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.FNAM, out var FNAMInfo))
            {
                yield return FNAMInfo;
            }
            yield break;
        }
        
