        public Package Duplicate(
            IPackageGetter item,
            FormKey formKey,
            TranslationCrystal? copyMask)
        {
            var newRec = new Package(formKey, item.FormVersion);
            newRec.DeepCopyIn(item, default(ErrorMaskBuilder?), copyMask);
            return newRec;
        }
        
